def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find square frames with a uniform border and a uniformly colored interior.
    for size in range(3, min(h, w) + 1):
        for r in range(h - size + 1):
            for c in range(w - size + 1):
                border = grid[r][c]
                if any(grid[r][j] != border or grid[r + size - 1][j] != border
                       for j in range(c, c + size)):
                    continue
                if any(grid[i][c] != border or grid[i][c + size - 1] != border
                       for i in range(r, r + size)):
                    continue

                interior = grid[r + 1][c + 1]
                if interior == border:
                    continue
                if any(grid[i][j] != interior
                       for i in range(r + 1, r + size - 1)
                       for j in range(c + 1, c + size - 1)):
                    continue

                fill = 7 if (size - 2) % 2 else 2
                for i in range(r + 1, r + size - 1):
                    for j in range(c + 1, c + size - 1):
                        out[i][j] = fill

    return out
